#!/usr/bin/env python3
"""pasang_antarmuka.py - memasang antarmuka web ke ~/projects/antarmuka/ (backend dan frontend terpisah).

    python3 pasang_antarmuka.py

    antarmuka/backend/    app.py (server FastAPI), layanan.py (logika), jalankan.sh
    antarmuka/frontend/   index.html, gaya.css, aplikasi.js

Bila susunan lama (app.py dan web/ langsung di antarmuka/) sudah terpasang, berkas lamanya
dipindah ke antarmuka/_lama/. Berkas yang sudah ada dan berbeda dicadangkan sebagai <nama>.lama.
Tidak mengubah pipeline.
"""
import json, os, shutil

TUJUAN = os.path.expanduser("~/projects/antarmuka")
BERKAS = json.loads(r'''{"backend/app.py": "\"\"\"\napp.py - server FastAPI untuk antarmuka web pipeline deteksi dan penghitungan kendaraan.\n\nJalankan (dari folder backend ini, dengan venv aktif):\n    uvicorn app:app --host 127.0.0.1 --port 8000\nlalu buka http://127.0.0.1:8000 di peramban.\n\nSemua logika ada di layanan.py; berkas ini hanya memetakan alamat web ke fungsi di sana.\nHalaman web (HTML/CSS/JS) ada di ../frontend dan disajikan oleh server ini.\n\"\"\"\n\nimport os\nfrom contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI, File, Form, HTTPException, UploadFile\nfrom fastapi.responses import FileResponse\nfrom fastapi.staticfiles import StaticFiles\n\nimport layanan\n\nWEB = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), \"frontend\")\n\n\n@asynccontextmanager\nasync def _siklus(_app):\n    layanan.muat_dari_disk()      # baca riwayat pekerjaan saat server mulai\n    yield\n\n\napp = FastAPI(title=\"Penghitung Kendaraan 3D\", lifespan=_siklus)\n\n\n@app.get(\"/api/info\")\ndef info():\n    return layanan.info()\n\n\n@app.get(\"/api/jobs\")\ndef daftar():\n    return layanan.daftar_job()\n\n\n@app.post(\"/api/jobs\")\ndef buat(\n    video: str = Form(\"\"),\n    berkas: UploadFile = File(None),\n    conf: str = Form(\"\"),\n    conf_low: str = Form(\"\"),\n    line_y: str = Form(\"\"),\n    line_y_away: str = Form(\"\"),\n):\n    setelan = {\"conf\": conf, \"conf_low\": conf_low, \"line_y\": line_y, \"line_y_away\": line_y_away}\n    try:\n        if berkas is not None and berkas.filename:\n            return layanan.buat_job(unggahan=berkas.file, nama_unggahan=berkas.filename, setelan=setelan)\n        return layanan.buat_job(nama_video=video, setelan=setelan)\n    except ValueError as e:\n        raise HTTPException(status_code=400, detail=str(e))\n\n\n@app.get(\"/api/jobs/{job_id}\")\ndef satu(job_id: str):\n    st = layanan.ambil_job(job_id)\n    if st is None:\n        raise HTTPException(status_code=404, detail=\"Pekerjaan tidak ditemukan.\")\n    return st\n\n\n@app.delete(\"/api/jobs/{job_id}\")\ndef hapus(job_id: str):\n    hasil = layanan.hapus_job(job_id)\n    if hasil == \"tidak ada\":\n        raise HTTPException(status_code=404, detail=\"Pekerjaan tidak ditemukan.\")\n    if hasil == \"sedang berjalan\":\n        raise HTTPException(status_code=409, detail=\"Pekerjaan masih berjalan.\")\n    return {\"ok\": True}\n\n\n@app.get(\"/api/jobs/{job_id}/berkas/{nama}\")\ndef berkas_hasil(job_id: str, nama: str):\n    p = layanan.jalur_berkas(job_id, nama)\n    if p is None:\n        raise HTTPException(status_code=404, detail=\"Berkas tidak ada.\")\n    jenis = {\"hasil.mp4\": \"video/mp4\", \"counting_log.csv\": \"text/csv\", \"keluaran.txt\": \"text/plain\"}[nama]\n    return FileResponse(p, media_type=jenis, filename=None if nama == \"hasil.mp4\" else nama)\n\n\n# halaman web (harus terakhir agar tidak menutupi /api)\napp.mount(\"/\", StaticFiles(directory=WEB, html=True), name=\"web\")\n", "backend/layanan.py": "\"\"\"\nlayanan.py - logika antarmuka: mengelola pekerjaan (job) yang menjalankan pipeline run.py\ndan meringkas hasilnya. Tidak bergantung pada FastAPI, sehingga bisa diuji sendiri.\n\nSatu job = satu video diproses. Job dijalankan SATU per satu (antrean), karena run.py\nmenulis counting_log.csv di folder pipeline dan mesin ini tanpa GPU.\n\nFolder tiap job: ~/projects/hasil/antarmuka/<id>/\n    status.json        keadaan job (antre/proses/selesai/gagal, progres, setelan)\n    hasil.mp4          video dengan kotak 3D\n    counting_log.csv   satu baris per kendaraan yang dihitung\n    ringkasan.json     hitungan per kelas, per arah, per rentang waktu\n    keluaran.txt       keluaran terminal run.py (untuk mencari penyebab bila gagal)\n\"\"\"\n\nimport csv\nimport importlib.util\nimport json\nimport os\nimport queue\nimport re\nimport secrets\nimport shutil\nimport subprocess\nimport sys\nimport threading\nimport time\n\nPROYEK = os.path.expanduser(os.environ.get(\"ANTARMUKA_PROYEK\", \"~/projects\"))\nPIPELINE = os.environ.get(\"ANTARMUKA_PIPELINE\", os.path.join(PROYEK, \"uji_session0_pipeline\"))\nDATA = os.path.join(PROYEK, \"hasil\", \"antarmuka\")\nVIDEO_DIR = os.path.join(PROYEK, \"video_uji\")\nMODEL = os.environ.get(\"ANTARMUKA_MODEL\", os.path.join(PROYEK, \"bobot\", \"detektor\", \"centernet_dari_baru.pth\"))\nPYTHON = sys.executable\nEKSTENSI = (\".mp4\", \".avi\", \".mov\", \".mkv\")\nMAKS_UNGGAH = 500 * 1024 * 1024          # byte\nCACHE_KHUSUS = {\"uji_val_720p.mp4\": \"det_session0.pkl\"}   # cache deteksi yang sudah ada\nID_SAH = re.compile(r\"^\\d{8}-\\d{6}-[0-9a-f]{4}$\")\nPOLA_PROGRES = re.compile(rb\"(\\d+)/(\\d+) \\[\")              # baris progres tqdm\n\n_kunci = threading.Lock()\n_jobs = {}                 # id -> status (dict)\n_antrean = queue.Queue()\n_pekerja = None\n\n\ndef _muat_config():\n    spec = importlib.util.spec_from_file_location(\"config_pipeline\", os.path.join(PIPELINE, \"config.py\"))\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\n\ncfg = _muat_config()\n\n\ndef _hex(bgr):\n    b, g, r = bgr\n    return \"#%02x%02x%02x\" % (r, g, b)\n\n\ndef daftar_video():\n    out = []\n    if os.path.isdir(VIDEO_DIR):\n        for n in sorted(os.listdir(VIDEO_DIR)):\n            if n.lower().endswith(EKSTENSI):\n                out.append({\"nama\": n, \"ada_cache\": os.path.exists(_jalur_cache(os.path.join(VIDEO_DIR, n)))})\n    return out\n\n\ndef info():\n    run_py = open(os.path.join(PIPELINE, \"run.py\"), encoding=\"utf-8\").read()\n    masalah = []\n    if '\"--out\"' not in run_py:\n        masalah.append(\"run.py belum bisa menyimpan video (jalankan alat/pasang_video.py di folder pipeline).\")\n    if not os.path.exists(MODEL):\n        masalah.append(\"Bobot detektor tidak ada: \" + MODEL)\n    if not shutil.which(\"ffmpeg\"):\n        masalah.append(\"ffmpeg belum terpasang; video hasil mungkin tidak bisa diputar di peramban (sudo apt install ffmpeg).\")\n    warna = getattr(cfg, \"CLASS_COLORS\", {})\n    return {\n        \"kelas\": [{\"nama\": c, \"warna\": _hex(warna.get(c, (200, 200, 200)))} for c in cfg.CLASSES],\n        \"bawaan\": {\"conf\": 0.4, \"conf_low\": 0.2, \"line_y\": cfg.LINE_Y_DEFAULT_M,\n                   \"line_y_away\": getattr(cfg, \"LINE_Y_AWAY_M\", cfg.LINE_Y_DEFAULT_M)},\n        \"median_x\": getattr(cfg, \"MEDIAN_X_M\", None),\n        \"video\": daftar_video(),\n        \"model\": os.path.basename(MODEL),\n        \"masalah\": masalah,\n    }\n\n\n# ------------------------------------------------------------------ penyimpanan status\ndef _folder(job_id):\n    return os.path.join(DATA, job_id)\n\n\ndef _simpan(st):\n    tmp = os.path.join(_folder(st[\"id\"]), \"status.json.tmp\")\n    with open(tmp, \"w\", encoding=\"utf-8\") as f:\n        json.dump(st, f, ensure_ascii=False, indent=1)\n    os.replace(tmp, os.path.join(_folder(st[\"id\"]), \"status.json\"))\n\n\ndef _ubah(job_id, **kw):\n    with _kunci:\n        st = _jobs[job_id]\n        st.update(kw)\n        _simpan(st)\n\n\ndef muat_dari_disk():\n    \"\"\"Dipanggil saat server mulai: baca job lama; job yang terputus ditandai gagal.\"\"\"\n    os.makedirs(DATA, exist_ok=True)\n    with _kunci:\n        for n in sorted(os.listdir(DATA)):\n            p = os.path.join(DATA, n, \"status.json\")\n            if not ID_SAH.match(n) or not os.path.exists(p):\n                continue\n            st = json.load(open(p, encoding=\"utf-8\"))\n            if st.get(\"status\") in (\"antre\", \"proses\"):\n                st.update(status=\"gagal\", pesan=\"Server dimulai ulang saat video ini sedang diproses.\")\n                _jobs[n] = st\n                _simpan(st)\n            _jobs[n] = st\n\n\ndef daftar_job():\n    with _kunci:\n        return sorted((dict(s) for s in _jobs.values()), key=lambda s: s[\"id\"], reverse=True)\n\n\ndef ambil_job(job_id):\n    with _kunci:\n        st = _jobs.get(job_id)\n        if st is None:\n            return None\n        st = dict(st)\n    p = os.path.join(_folder(job_id), \"ringkasan.json\")\n    if st[\"status\"] == \"selesai\" and os.path.exists(p):\n        st[\"ringkasan\"] = json.load(open(p, encoding=\"utf-8\"))\n    return st\n\n\ndef jalur_berkas(job_id, nama):\n    \"\"\"Jalur berkas hasil milik job (hanya nama yang diizinkan), atau None.\"\"\"\n    if not ID_SAH.match(job_id) or nama not in (\"hasil.mp4\", \"counting_log.csv\", \"keluaran.txt\"):\n        return None\n    p = os.path.join(_folder(job_id), nama)\n    return p if os.path.exists(p) else None\n\n\ndef hapus_job(job_id):\n    with _kunci:\n        st = _jobs.get(job_id)\n        if st is None:\n            return \"tidak ada\"\n        if st[\"status\"] in (\"antre\", \"proses\"):\n            return \"sedang berjalan\"\n        del _jobs[job_id]\n    shutil.rmtree(_folder(job_id), ignore_errors=True)\n    return \"ok\"\n\n\n# ------------------------------------------------------------------ membuat job\ndef _angka(nilai, bawaan, lo, hi):\n    try:\n        v = float(nilai)\n    except (TypeError, ValueError):\n        return bawaan\n    return min(max(v, lo), hi)\n\n\ndef buat_job(nama_video=None, unggahan=None, nama_unggahan=None, setelan=None):\n    \"\"\"\n    nama_video : nama berkas di folder video_uji, ATAU\n    unggahan   : objek berkas (punya .read(n)) + nama_unggahan.\n    Mengembalikan status job. ValueError bila masukan tidak sah.\n    \"\"\"\n    setelan = setelan or {}\n    b = info()[\"bawaan\"]\n    s = {\n        \"conf\": _angka(setelan.get(\"conf\"), b[\"conf\"], 0.05, 0.95),\n        \"conf_low\": _angka(setelan.get(\"conf_low\"), b[\"conf_low\"], 0.0, 0.9),\n        \"line_y\": _angka(setelan.get(\"line_y\"), b[\"line_y\"], 5.0, 200.0),\n        \"line_y_away\": _angka(setelan.get(\"line_y_away\"), b[\"line_y_away\"], 5.0, 200.0),\n    }\n    if s[\"conf_low\"] >= s[\"conf\"]:\n        raise ValueError(\"Ambang rendah harus lebih kecil dari ambang deteksi (atau 0 untuk mematikan).\")\n\n    job_id = time.strftime(\"%Y%m%d-%H%M%S-\") + secrets.token_hex(2)\n    os.makedirs(_folder(job_id))\n    try:\n        if unggahan is not None:\n            eks = os.path.splitext(nama_unggahan or \"\")[1].lower()\n            if eks not in EKSTENSI:\n                raise ValueError(\"Jenis berkas tidak didukung. Pakai: \" + \", \".join(EKSTENSI))\n            jalur = os.path.join(_folder(job_id), \"masukan\" + eks)\n            total = 0\n            with open(jalur, \"wb\") as f:\n                while True:\n                    potong = unggahan.read(1024 * 1024)\n                    if not potong:\n                        break\n                    total += len(potong)\n                    if total > MAKS_UNGGAH:\n                        raise ValueError(\"Berkas terlalu besar (maksimum %d MB).\" % (MAKS_UNGGAH // 1024 // 1024))\n                    f.write(potong)\n            if total == 0:\n                raise ValueError(\"Berkas kosong.\")\n            nama, cache = os.path.basename(nama_unggahan), os.path.join(_folder(job_id), \"deteksi.pkl\")\n        else:\n            if nama_video not in [v[\"nama\"] for v in daftar_video()]:\n                raise ValueError(\"Video tidak ditemukan di folder video_uji.\")\n            jalur = os.path.join(VIDEO_DIR, nama_video)\n            nama, cache = nama_video, _jalur_cache(jalur)\n    except Exception:\n        shutil.rmtree(_folder(job_id), ignore_errors=True)\n        raise\n\n    st = {\"id\": job_id, \"nama_video\": nama, \"dibuat\": time.strftime(\"%Y-%m-%d %H:%M:%S\"), \"status\": \"antre\",\n          \"tahap\": \"Menunggu giliran\", \"progres\": 0.0, \"setelan\": s, \"masukan\": jalur, \"cache\": cache, \"pesan\": \"\"}\n    with _kunci:\n        _jobs[job_id] = st\n        _simpan(st)\n    _mulai_pekerja()\n    _antrean.put(job_id)\n    return dict(st)\n\n\ndef _jalur_cache(jalur_video):\n    khusus = CACHE_KHUSUS.get(os.path.basename(jalur_video))\n    if khusus and os.path.exists(os.path.join(os.path.dirname(jalur_video), khusus)):\n        return os.path.join(os.path.dirname(jalur_video), khusus)\n    return jalur_video + \".det.pkl\"\n\n\n# ------------------------------------------------------------------ menjalankan pipeline\ndef _mulai_pekerja():\n    global _pekerja\n    with _kunci:\n        if _pekerja is None or not _pekerja.is_alive():\n            _pekerja = threading.Thread(target=_putaran, daemon=True)\n            _pekerja.start()\n\n\ndef _putaran():\n    while True:\n        job_id = _antrean.get()\n        try:\n            _kerjakan(job_id)\n        except Exception as e:                      # jangan sampai pekerja mati\n            try:\n                _ubah(job_id, status=\"gagal\", tahap=\"Gagal\", pesan=\"Galat internal: %s\" % e)\n            except Exception:\n                pass\n\n\ndef _siapkan_video(job_id, jalur):\n    \"\"\"Pastikan video berukuran IMG_W x IMG_H; bila tidak, buat salinan yang diubah ukurannya.\"\"\"\n    import cv2\n    cap = cv2.VideoCapture(jalur)\n    if not cap.isOpened():\n        raise RuntimeError(\"Video tidak bisa dibuka.\")\n    w, h = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH)), int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))\n    n, fps = int(cap.get(cv2.CAP_PROP_FRAME_COUNT)), cap.get(cv2.CAP_PROP_FPS)\n    fps = fps if fps and fps > 1 else 25.0\n    if (w, h) == (cfg.IMG_W, cfg.IMG_H):\n        cap.release()\n        return jalur, n, fps\n    _ubah(job_id, tahap=\"Mengubah ukuran video ke %dx%d\" % (cfg.IMG_W, cfg.IMG_H))\n    baru = os.path.join(_folder(job_id), \"masukan_%dp.mp4\" % cfg.IMG_H)\n    out = cv2.VideoWriter(baru, cv2.VideoWriter_fourcc(*\"mp4v\"), fps, (cfg.IMG_W, cfg.IMG_H))\n    i = 0\n    while True:\n        ok, fr = cap.read()\n        if not ok:\n            break\n        out.write(cv2.resize(fr, (cfg.IMG_W, cfg.IMG_H), interpolation=cv2.INTER_AREA))\n        i += 1\n        if i % 25 == 0 and n:\n            _ubah(job_id, progres=round(0.1 * i / n, 3))\n    cap.release()\n    out.release()\n    return baru, i, fps\n\n\ndef _kerjakan(job_id):\n    st = ambil_job(job_id)\n    if st is None:\n        return\n    folder, s = _folder(job_id), st[\"setelan\"]\n    _ubah(job_id, status=\"proses\", tahap=\"Menyiapkan video\", mulai=time.time())\n    try:\n        video, n_frame, fps = _siapkan_video(job_id, st[\"masukan\"])\n    except Exception as e:\n        _ubah(job_id, status=\"gagal\", tahap=\"Gagal\", pesan=str(e))\n        return\n    pakai_cache = os.path.exists(st[\"cache\"])\n    _ubah(job_id, frame_total=n_frame, fps=fps,\n          tahap=\"Melacak dan menghitung (deteksi dari cache)\" if pakai_cache else \"Mendeteksi kendaraan (tanpa GPU, lambat)\")\n\n    cmd = [PYTHON, \"run.py\", video, MODEL, \"--no-show\", \"--out\", os.path.join(folder, \"hasil.mp4\"),\n           \"--cache\", st[\"cache\"], \"--conf\", str(s[\"conf\"]),\n           \"--line-y\", str(s[\"line_y\"]), \"--line-y-away\", str(s[\"line_y_away\"])]\n    if s[\"conf_low\"] > 0:\n        cmd += [\"--conf-low\", str(s[\"conf_low\"])]\n    cmd += os.environ.get(\"ANTARMUKA_ARG_TAMBAHAN\", \"\").split()   # mis. --tanpa-gambar\n    log = open(os.path.join(folder, \"keluaran.txt\"), \"wb\")\n    p = subprocess.Popen(cmd, cwd=PIPELINE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)\n    baris, terakhir = b\"\", 0.0\n    while True:\n        c = p.stdout.read(1)\n        if not c:\n            break\n        if c in (b\"\\r\", b\"\\n\"):\n            m = POLA_PROGRES.search(baris)\n            if m and int(m.group(2)) > 0:\n                if time.time() - terakhir > 0.5:\n                    terakhir = time.time()\n                    _ubah(job_id, progres=round(0.1 + 0.85 * int(m.group(1)) / int(m.group(2)), 3))\n            elif baris.strip():\n                log.write(baris + b\"\\n\")\n                log.flush()\n            baris = b\"\"\n        else:\n            baris += c\n    kode = p.wait()\n    log.close()\n    if kode != 0:\n        ekor = open(os.path.join(folder, \"keluaran.txt\"), errors=\"replace\").read()[-600:]\n        _ubah(job_id, status=\"gagal\", tahap=\"Gagal\", pesan=\"Pipeline berhenti dengan galat:\\n\" + ekor)\n        return\n    try:\n        shutil.copy(os.path.join(PIPELINE, cfg.COUNT_LOG), os.path.join(folder, \"counting_log.csv\"))\n        r = ringkas(os.path.join(folder, \"counting_log.csv\"), fps, n_frame)\n        json.dump(r, open(os.path.join(folder, \"ringkasan.json\"), \"w\", encoding=\"utf-8\"), ensure_ascii=False, indent=1)\n    except Exception as e:\n        _ubah(job_id, status=\"gagal\", tahap=\"Gagal\", pesan=\"Hasil tidak bisa dibaca: %s\" % e)\n        return\n    st2 = ambil_job(job_id)\n    _ubah(job_id, status=\"selesai\", tahap=\"Selesai\", progres=1.0, total=r[\"total\"],\n          lama_detik=round(time.time() - st2.get(\"mulai\", time.time()), 1),\n          ada_video=os.path.exists(os.path.join(folder, \"hasil.mp4\")))\n\n\n# ------------------------------------------------------------------ ringkasan hasil\ndef ringkas(csv_path, fps, n_frame):\n    \"\"\"Ringkas counting_log.csv: per kelas, per arah, per rentang waktu, dan daftar kendaraan.\"\"\"\n    kelas = list(cfg.CLASSES)\n    median = getattr(cfg, \"MEDIAN_X_M\", None)\n    durasi = n_frame / fps if fps else 0.0\n    langkah = next((x for x in (5, 10, 15, 30, 60, 120, 300, 600, 1800, 3600) if durasi / x <= 12), 3600)\n    n_bak = max(1, int(durasi // langkah) + (1 if durasi % langkah else 0))\n    waktu = [{\"mulai\": i * langkah, **{c: 0 for c in kelas}} for i in range(n_bak)]\n    per_kelas = {c: 0 for c in kelas}\n    per_arah = {\"mendekat\": 0, \"menjauh\": 0}\n    kendaraan = []\n    with open(csv_path, newline=\"\", encoding=\"utf-8\") as f:\n        for r in csv.DictReader(f):\n            k = r[\"kelas\"]\n            if k not in per_kelas:\n                continue\n            fr, x = int(r[\"frame\"]), float(r[\"x_m\"])\n            t = fr / fps if fps else 0.0\n            arah = \"menjauh\" if (median is not None and x >= median) else \"mendekat\"\n            per_kelas[k] += 1\n            per_arah[arah] += 1\n            waktu[min(int(t // langkah), n_bak - 1)][k] += 1\n            skor = r.get(\"suara_\" + k, \"\")\n            kendaraan.append({\"frame\": fr, \"detik\": round(t, 2), \"id\": int(r[\"id\"]), \"kelas\": k, \"arah\": arah,\n                              \"panjang_m\": float(r[\"panjang_m\"]), \"x_m\": x,\n                              \"skor\": float(skor) if skor not in (\"\", None) else None})\n    return {\"total\": len(kendaraan), \"per_kelas\": per_kelas, \"per_arah\": per_arah, \"ada_arah\": median is not None,\n            \"durasi_detik\": round(durasi, 1), \"langkah_detik\": langkah, \"per_waktu\": waktu, \"kendaraan\": kendaraan}\n", "backend/jalankan.sh": "#!/bin/bash\n# Menjalankan server antarmuka. Buka http://127.0.0.1:8000 di peramban. Berhenti: Ctrl+C.\ncd \"$(dirname \"$0\")\" || exit 1\nsource ~/projects/venv_3dbbox/bin/activate\nexec uvicorn app:app --host 127.0.0.1 --port 8000\n", "frontend/index.html": "<!doctype html>\n<html lang=\"id\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Penghitung Kendaraan 3D</title>\n<link rel=\"stylesheet\" href=\"gaya.css\">\n</head>\n<body>\n<header class=\"atas\">\n  <div>\n    <h1>Penghitung Kendaraan 3D</h1>\n    <p class=\"sub\">Deteksi kotak 3D, pelacakan, klasifikasi 4 kelas, dan penghitungan</p>\n  </div>\n  <div id=\"model\" class=\"lencana\"></div>\n</header>\n\n<div id=\"masalah\" class=\"peringatan\" hidden></div>\n\n<main class=\"tata\">\n  <aside class=\"samping\">\n    <section class=\"kartu\">\n      <h2>Proses video</h2>\n      <form id=\"form\">\n        <label for=\"video\">Video di server</label>\n        <select id=\"video\" name=\"video\"></select>\n\n        <label for=\"berkas\">atau unggah video</label>\n        <input id=\"berkas\" name=\"berkas\" type=\"file\" accept=\".mp4,.avi,.mov,.mkv,video/*\">\n\n        <details>\n          <summary>Setelan</summary>\n          <div class=\"kisi2\">\n            <div><label for=\"conf\">Ambang deteksi</label><input id=\"conf\" name=\"conf\" type=\"number\" step=\"0.05\" min=\"0.05\" max=\"0.95\"></div>\n            <div><label for=\"conf_low\">Ambang rendah</label><input id=\"conf_low\" name=\"conf_low\" type=\"number\" step=\"0.05\" min=\"0\" max=\"0.9\"></div>\n            <div><label for=\"line_y\">Garis mendekat (m)</label><input id=\"line_y\" name=\"line_y\" type=\"number\" step=\"1\" min=\"5\" max=\"200\"></div>\n            <div><label for=\"line_y_away\">Garis menjauh (m)</label><input id=\"line_y_away\" name=\"line_y_away\" type=\"number\" step=\"1\" min=\"5\" max=\"200\"></div>\n          </div>\n        </details>\n\n        <button id=\"tombol\" type=\"submit\">Proses</button>\n        <p id=\"galat_form\" class=\"galat\" hidden></p>\n      </form>\n    </section>\n\n    <section class=\"kartu\">\n      <h2>Riwayat</h2>\n      <ul id=\"riwayat\" class=\"riwayat\"></ul>\n      <p id=\"riwayat_kosong\" class=\"redup\">Belum ada video yang diproses.</p>\n    </section>\n  </aside>\n\n  <section class=\"utama\">\n    <div id=\"kosong\" class=\"kartu tengah\">\n      <p>Pilih video lalu tekan <b>Proses</b>, atau buka salah satu hasil di Riwayat.</p>\n    </div>\n\n    <div id=\"berjalan\" class=\"kartu\" hidden>\n      <h2 id=\"berjalan_judul\"></h2>\n      <p id=\"berjalan_tahap\" class=\"redup\"></p>\n      <div class=\"batang\" role=\"progressbar\" aria-valuemin=\"0\" aria-valuemax=\"100\"><div id=\"batang_isi\"></div></div>\n      <p id=\"berjalan_persen\" class=\"redup\"></p>\n    </div>\n\n    <div id=\"gagal\" class=\"kartu\" hidden>\n      <h2 id=\"gagal_judul\"></h2>\n      <p class=\"galat\">Pemrosesan gagal.</p>\n      <pre id=\"gagal_pesan\"></pre>\n      <button id=\"gagal_hapus\" class=\"polos\" type=\"button\">Hapus dari riwayat</button>\n    </div>\n\n    <div id=\"hasil\" hidden>\n      <div class=\"kartu\">\n        <div class=\"baris_judul\">\n          <h2 id=\"hasil_judul\"></h2>\n          <div class=\"aksi\">\n            <a id=\"unduh_csv\" class=\"tautan\" download>Unduh CSV</a>\n            <button id=\"hasil_hapus\" class=\"polos\" type=\"button\">Hapus</button>\n          </div>\n        </div>\n        <p id=\"hasil_info\" class=\"redup\"></p>\n        <video id=\"pemutar\" controls preload=\"metadata\"></video>\n        <p id=\"tanpa_video\" class=\"redup\" hidden>Video hasil tidak tersedia untuk pekerjaan ini.</p>\n      </div>\n\n      <div id=\"kartu_angka\" class=\"angka\"></div>\n\n      <div class=\"kartu\">\n        <h2>Kendaraan per rentang waktu</h2>\n        <div id=\"grafik\"></div>\n        <div id=\"legenda\" class=\"legenda\"></div>\n      </div>\n\n      <div class=\"kartu\">\n        <h2>Kendaraan yang dihitung</h2>\n        <p class=\"redup\">Klik baris untuk melompat ke saat kendaraan itu melintasi garis.</p>\n        <div class=\"gulir\">\n          <table>\n            <thead><tr><th>Waktu</th><th>ID</th><th>Kelas</th><th>Arah</th><th class=\"kanan\">Panjang (m)</th><th class=\"kanan\">Skor kelas</th></tr></thead>\n            <tbody id=\"tabel\"></tbody>\n          </table>\n        </div>\n        <p id=\"tabel_kosong\" class=\"redup\" hidden>Tidak ada kendaraan yang melintasi garis.</p>\n      </div>\n    </div>\n  </section>\n</main>\n<script src=\"aplikasi.js\"></script>\n</body>\n</html>\n", "frontend/gaya.css": ":root {\n  --latar: #f4f5f7; --kartu: #ffffff; --teks: #1b1f24; --redup: #5c6773; --garis: #dfe3e8;\n  --aksen: #1f5fbf; --aksen-teks: #ffffff; --galat: #b3261e; --peringatan-latar: #fff4d6; --peringatan-teks: #5c4400;\n  --pilih: #e8f0fc;\n}\n@media (prefers-color-scheme: dark) {\n  :root {\n    --latar: #13161a; --kartu: #1c2026; --teks: #e7eaee; --redup: #9aa5b1; --garis: #2e353e;\n    --aksen: #6ea8ff; --aksen-teks: #0c1420; --galat: #ff8a80; --peringatan-latar: #3a3112; --peringatan-teks: #f2dfa0;\n    --pilih: #24324a;\n  }\n}\n* { box-sizing: border-box; }\nbody { margin: 0; background: var(--latar); color: var(--teks);\n  font: 15px/1.5 system-ui, -apple-system, \"Segoe UI\", Roboto, \"Noto Sans\", sans-serif; }\nh1 { font-size: 20px; margin: 0; }\nh2 { font-size: 15px; margin: 0 0 10px; }\n.sub { margin: 2px 0 0; color: var(--redup); font-size: 13px; }\n.redup { color: var(--redup); font-size: 13px; margin: 6px 0; }\n.galat { color: var(--galat); font-size: 13px; margin: 8px 0 0; }\n.atas { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap;\n  padding: 14px 20px; background: var(--kartu); border-bottom: 1px solid var(--garis); }\n.lencana { font-size: 12px; color: var(--redup); border: 1px solid var(--garis); border-radius: 999px; padding: 3px 10px; }\n.peringatan { margin: 12px 20px 0; padding: 10px 14px; border-radius: 8px; font-size: 13px;\n  background: var(--peringatan-latar); color: var(--peringatan-teks); }\n.peringatan p { margin: 2px 0; }\n.tata { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 16px; padding: 16px 20px 40px; max-width: 1280px; margin: 0 auto; }\n@media (max-width: 820px) { .tata { grid-template-columns: minmax(0, 1fr); padding: 12px 16px 32px; } }\n.samping, .utama { display: flex; flex-direction: column; gap: 16px; min-width: 0; }\n#hasil { display: flex; flex-direction: column; gap: 16px; }\n#hasil[hidden] { display: none; }\n.kartu { background: var(--kartu); border: 1px solid var(--garis); border-radius: 10px; padding: 16px; min-width: 0; }\n.tengah { text-align: center; color: var(--redup); padding: 48px 16px; }\nlabel { display: block; font-size: 12px; color: var(--redup); margin: 10px 0 4px; }\nselect, input[type=number], input[type=file] { width: 100%; padding: 7px 8px; border: 1px solid var(--garis); border-radius: 6px;\n  background: var(--latar); color: var(--teks); font: inherit; font-size: 14px; }\ndetails { margin-top: 12px; }\nsummary { cursor: pointer; font-size: 13px; color: var(--redup); }\n.kisi2 { display: grid; grid-template-columns: 1fr 1fr; gap: 0 10px; }\nbutton { font: inherit; cursor: pointer; border-radius: 6px; }\n#tombol { width: 100%; margin-top: 14px; padding: 9px; border: 0; background: var(--aksen); color: var(--aksen-teks); font-weight: 600; }\n#tombol:disabled { opacity: .6; cursor: default; }\n.polos { background: none; border: 1px solid var(--garis); color: var(--teks); padding: 5px 10px; font-size: 13px; }\n.tautan { color: var(--aksen); font-size: 13px; text-decoration: none; }\n.tautan:hover { text-decoration: underline; }\n.riwayat { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; max-height: 340px; overflow-y: auto; }\n.riwayat button { width: 100%; text-align: left; background: none; border: 1px solid transparent; padding: 7px 8px; color: var(--teks); }\n.riwayat button:hover { border-color: var(--garis); }\n.riwayat button.aktif { background: var(--pilih); border-color: var(--garis); }\n.riwayat .nama { display: block; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.riwayat .ket { display: block; font-size: 12px; color: var(--redup); }\n.batang { height: 10px; background: var(--latar); border: 1px solid var(--garis); border-radius: 999px; overflow: hidden; margin-top: 10px; }\n#batang_isi { height: 100%; width: 0; background: var(--aksen); transition: width .4s; }\npre { white-space: pre-wrap; word-break: break-word; font-size: 12px; background: var(--latar); border: 1px solid var(--garis);\n  border-radius: 6px; padding: 10px; max-height: 260px; overflow: auto; }\n.baris_judul { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; }\n.baris_judul h2 { margin: 0; overflow-wrap: anywhere; }\n.aksi { display: flex; align-items: center; gap: 12px; }\nvideo { width: 100%; border-radius: 6px; background: #000; margin-top: 8px; aspect-ratio: 16 / 9; }\n.angka { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 12px; }\n.angka .kartu { padding: 12px 14px; }\n.angka .judul { font-size: 12px; color: var(--redup); display: flex; align-items: center; gap: 6px; }\n.angka .nilai { font-size: 28px; font-weight: 650; line-height: 1.2; font-variant-numeric: tabular-nums; }\n.titik { width: 10px; height: 10px; border-radius: 3px; display: inline-block; flex: none; border: 1px solid rgba(0,0,0,.25); }\n#grafik svg { width: 100%; height: auto; display: block; }\n#grafik text { fill: var(--redup); font-size: 11px; }\n#grafik .sumbu { stroke: var(--garis); }\n.legenda { display: flex; gap: 14px; flex-wrap: wrap; font-size: 12px; color: var(--redup); margin-top: 6px; }\n.legenda span { display: inline-flex; align-items: center; gap: 5px; }\n.gulir { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; }\nth { text-align: left; color: var(--redup); font-weight: 500; font-size: 12px; padding: 6px 8px; border-bottom: 1px solid var(--garis); white-space: nowrap; }\ntd { padding: 7px 8px; border-bottom: 1px solid var(--garis); white-space: nowrap; }\ntbody tr { cursor: pointer; }\ntbody tr:hover { background: var(--pilih); }\n.kanan { text-align: right; }\ntd .titik { margin-right: 6px; vertical-align: baseline; }\n", "frontend/aplikasi.js": "// Antarmuka web: memanggil API server (app.py) dan menampilkan hasil.\n\"use strict\";\n\nconst $ = (id) => document.getElementById(id);\nlet INFO = null;          // dari /api/info\nlet aktif = null;         // id job yang sedang ditampilkan\nlet pengatur = null;      // timer polling\n\nfunction el(tag, kelas, teks) {\n  const e = document.createElement(tag);\n  if (kelas) e.className = kelas;\n  if (teks !== undefined) e.textContent = teks;\n  return e;\n}\nfunction warna(kelas) {\n  const k = INFO.kelas.find((x) => x.nama === kelas);\n  return k ? k.warna : \"#999999\";\n}\nfunction jam(detik) {\n  const m = Math.floor(detik / 60), s = detik - m * 60;\n  return m + \":\" + (s < 10 ? \"0\" : \"\") + s.toFixed(1);\n}\nasync function api(jalur, opsi) {\n  const r = await fetch(jalur, opsi);\n  if (!r.ok) {\n    let pesan = \"Permintaan gagal (\" + r.status + \")\";\n    try { const j = await r.json(); if (j.detail) pesan = j.detail; } catch (e) { /* bukan JSON */ }\n    throw new Error(pesan);\n  }\n  return r.json();\n}\n\n// ---------------------------------------------------------------- awal\nasync function mulai() {\n  INFO = await api(\"/api/info\");\n  $(\"model\").textContent = \"Model: \" + INFO.model;\n  if (INFO.masalah.length) {\n    const kotak = $(\"masalah\");\n    INFO.masalah.forEach((m) => kotak.appendChild(el(\"p\", \"\", m)));\n    kotak.hidden = false;\n  }\n  const pilih = $(\"video\");\n  if (!INFO.video.length) pilih.appendChild(new Option(\"(tidak ada video di server)\", \"\"));\n  INFO.video.forEach((v) => pilih.appendChild(new Option(v.nama + (v.ada_cache ? \"  (cepat: ada cache)\" : \"\"), v.nama)));\n  for (const k of [\"conf\", \"conf_low\", \"line_y\", \"line_y_away\"]) $(k).value = INFO.bawaan[k];\n  await muatRiwayat();\n}\n\n// ---------------------------------------------------------------- riwayat\nconst LABEL = { antre: \"menunggu\", proses: \"diproses\", selesai: \"selesai\", gagal: \"gagal\" };\nasync function muatRiwayat() {\n  const jobs = await api(\"/api/jobs\");\n  const ul = $(\"riwayat\");\n  ul.replaceChildren();\n  $(\"riwayat_kosong\").hidden = jobs.length > 0;\n  jobs.forEach((j) => {\n    const b = el(\"button\", j.id === aktif ? \"aktif\" : \"\");\n    b.type = \"button\";\n    b.appendChild(el(\"span\", \"nama\", j.nama_video));\n    let ket = j.dibuat + \" \u00b7 \" + LABEL[j.status];\n    if (j.status === \"selesai\") ket += \" \u00b7 \" + j.total + \" kendaraan\";\n    b.appendChild(el(\"span\", \"ket\", ket));\n    b.addEventListener(\"click\", () => buka(j.id));\n    const li = el(\"li\");\n    li.appendChild(b);\n    ul.appendChild(li);\n  });\n  return jobs;\n}\n\n// ---------------------------------------------------------------- form\n$(\"form\").addEventListener(\"submit\", async (ev) => {\n  ev.preventDefault();\n  const galat = $(\"galat_form\");\n  galat.hidden = true;\n  const data = new FormData($(\"form\"));\n  if (!$(\"berkas\").files.length) data.delete(\"berkas\");\n  if (!$(\"berkas\").files.length && !data.get(\"video\")) {\n    galat.textContent = \"Pilih video di server atau unggah berkas video.\";\n    galat.hidden = false;\n    return;\n  }\n  $(\"tombol\").disabled = true;\n  $(\"tombol\").textContent = \"Mengirim\u2026\";\n  try {\n    const j = await api(\"/api/jobs\", { method: \"POST\", body: data });\n    $(\"berkas\").value = \"\";\n    await buka(j.id);\n  } catch (e) {\n    galat.textContent = e.message;\n    galat.hidden = false;\n  } finally {\n    $(\"tombol\").disabled = false;\n    $(\"tombol\").textContent = \"Proses\";\n  }\n});\n\n// ---------------------------------------------------------------- tampilan job\nfunction tampil(nama) {\n  for (const n of [\"kosong\", \"berjalan\", \"gagal\", \"hasil\"]) $(n).hidden = n !== nama;\n}\nasync function buka(id) {\n  aktif = id;\n  clearTimeout(pengatur);\n  await segarkan();\n}\nasync function segarkan() {\n  if (!aktif) return;\n  let j;\n  try {\n    j = await api(\"/api/jobs/\" + aktif);\n  } catch (e) {\n    aktif = null;\n    tampil(\"kosong\");\n    await muatRiwayat();\n    return;\n  }\n  if (j.status === \"antre\" || j.status === \"proses\") {\n    tampil(\"berjalan\");\n    $(\"berjalan_judul\").textContent = j.nama_video;\n    $(\"berjalan_tahap\").textContent = j.tahap;\n    const p = Math.round((j.progres || 0) * 100);\n    $(\"batang_isi\").style.width = p + \"%\";\n    $(\"batang_isi\").parentElement.setAttribute(\"aria-valuenow\", p);\n    $(\"berjalan_persen\").textContent = p + \"%\" + (j.frame_total ? \" dari \" + j.frame_total + \" frame\" : \"\");\n    pengatur = setTimeout(segarkan, 1000);\n    await muatRiwayat();\n  } else if (j.status === \"gagal\") {\n    tampil(\"gagal\");\n    $(\"gagal_judul\").textContent = j.nama_video;\n    $(\"gagal_pesan\").textContent = j.pesan || \"(tidak ada keterangan)\";\n    await muatRiwayat();\n  } else {\n    gambarHasil(j);\n    tampil(\"hasil\");\n    await muatRiwayat();\n  }\n}\nasync function hapusAktif() {\n  if (!aktif || !confirm(\"Hapus hasil ini dari riwayat? Video hasil dan lognya ikut terhapus.\")) return;\n  try { await api(\"/api/jobs/\" + aktif, { method: \"DELETE\" }); } catch (e) { alert(e.message); return; }\n  aktif = null;\n  tampil(\"kosong\");\n  await muatRiwayat();\n}\n$(\"hasil_hapus\").addEventListener(\"click\", hapusAktif);\n$(\"gagal_hapus\").addEventListener(\"click\", hapusAktif);\n\n// ---------------------------------------------------------------- hasil\nfunction kartuAngka(judul, nilai, warnaTitik) {\n  const k = el(\"div\", \"kartu\");\n  const j = el(\"div\", \"judul\");\n  if (warnaTitik) { const t = el(\"span\", \"titik\"); t.style.background = warnaTitik; j.appendChild(t); }\n  j.appendChild(document.createTextNode(judul));\n  k.appendChild(j);\n  k.appendChild(el(\"div\", \"nilai\", String(nilai)));\n  return k;\n}\nfunction gambarHasil(j) {\n  const r = j.ringkasan;\n  const dasar = \"/api/jobs/\" + j.id + \"/berkas/\";\n  $(\"hasil_judul\").textContent = j.nama_video;\n  const s = j.setelan;\n  $(\"hasil_info\").textContent = \"Diproses \" + j.dibuat + \" \u00b7 durasi video \" + jam(r.durasi_detik) + \" \u00b7 \" + j.frame_total +\n    \" frame \u00b7 selesai dalam \" + j.lama_detik + \" detik \u00b7 garis \" + s.line_y + \" m\" + (r.ada_arah ? \" / \" + s.line_y_away + \" m\" : \"\");\n  $(\"unduh_csv\").href = dasar + \"counting_log.csv\";\n  const v = $(\"pemutar\");\n  v.hidden = !j.ada_video;\n  $(\"tanpa_video\").hidden = !!j.ada_video;\n  if (j.ada_video && v.dataset.id !== j.id) { v.src = dasar + \"hasil.mp4\"; v.dataset.id = j.id; }\n\n  const angka = $(\"kartu_angka\");\n  angka.replaceChildren(kartuAngka(\"Total\", r.total));\n  INFO.kelas.forEach((k) => angka.appendChild(kartuAngka(k.nama, r.per_kelas[k.nama] || 0, k.warna)));\n  if (r.ada_arah) {\n    angka.appendChild(kartuAngka(\"Mendekat\", r.per_arah.mendekat));\n    angka.appendChild(kartuAngka(\"Menjauh\", r.per_arah.menjauh));\n  }\n  gambarGrafik(r);\n\n  const tb = $(\"tabel\");\n  tb.replaceChildren();\n  $(\"tabel_kosong\").hidden = r.kendaraan.length > 0;\n  r.kendaraan.forEach((k) => {\n    const tr = el(\"tr\");\n    tr.appendChild(el(\"td\", \"\", jam(k.detik)));\n    tr.appendChild(el(\"td\", \"\", String(k.id)));\n    const td = el(\"td\");\n    const t = el(\"span\", \"titik\"); t.style.background = warna(k.kelas);\n    td.appendChild(t); td.appendChild(document.createTextNode(k.kelas));\n    tr.appendChild(td);\n    tr.appendChild(el(\"td\", \"\", r.ada_arah ? k.arah : \"-\"));\n    tr.appendChild(el(\"td\", \"kanan\", k.panjang_m.toFixed(2)));\n    tr.appendChild(el(\"td\", \"kanan\", k.skor === null ? \"-\" : k.skor.toFixed(2)));\n    tr.addEventListener(\"click\", () => {\n      if (!j.ada_video) return;\n      v.currentTime = Math.max(0, k.detik - 1);\n      v.play().catch(() => {});\n      v.scrollIntoView({ behavior: \"smooth\", block: \"center\" });\n    });\n    tb.appendChild(tr);\n  });\n}\n\n// grafik batang bertumpuk (SVG), satu batang per rentang waktu\nfunction gambarGrafik(r) {\n  const NS = \"http://www.w3.org/2000/svg\";\n  const W = 720, H = 220, kiri = 30, bawah = 24, atas = 10;\n  const svg = document.createElementNS(NS, \"svg\");\n  svg.setAttribute(\"viewBox\", \"0 0 \" + W + \" \" + H);\n  svg.setAttribute(\"role\", \"img\");\n  svg.setAttribute(\"aria-label\", \"Jumlah kendaraan per rentang waktu\");\n  const buat = (tag, attr, teks) => {\n    const e = document.createElementNS(NS, tag);\n    for (const k in attr) e.setAttribute(k, attr[k]);\n    if (teks !== undefined) e.textContent = teks;\n    svg.appendChild(e);\n    return e;\n  };\n  const data = r.per_waktu;\n  const jumlah = data.map((d) => INFO.kelas.reduce((a, k) => a + (d[k.nama] || 0), 0));\n  const maks = Math.max(1, ...jumlah);\n  const tinggi = H - bawah - atas, lebar = (W - kiri - 8) / data.length;\n  const langkahY = Math.max(1, Math.ceil(maks / 4));\n  for (let y = 0; y <= maks; y += langkahY) {\n    const py = atas + tinggi - (y / maks) * tinggi;\n    buat(\"line\", { x1: kiri, x2: W - 8, y1: py, y2: py, class: \"sumbu\" });\n    buat(\"text\", { x: kiri - 6, y: py + 4, \"text-anchor\": \"end\" }, String(y));\n  }\n  data.forEach((d, i) => {\n    let dasar = atas + tinggi;\n    const x = kiri + i * lebar + lebar * 0.18, w = lebar * 0.64;\n    INFO.kelas.forEach((k) => {\n      const n = d[k.nama] || 0;\n      if (!n) return;\n      const h = (n / maks) * tinggi;\n      dasar -= h;\n      const rect = buat(\"rect\", { x: x, y: dasar, width: w, height: h, fill: k.warna, rx: 2 });\n      const judul = document.createElementNS(NS, \"title\");\n      judul.textContent = jam(d.mulai) + \" \u2013 \" + jam(d.mulai + r.langkah_detik) + \": \" + n + \" \" + k.nama;\n      rect.appendChild(judul);\n    });\n    if (data.length <= 14 || i % 2 === 0) buat(\"text\", { x: x + w / 2, y: H - 7, \"text-anchor\": \"middle\" }, jam(d.mulai).replace(\".0\", \"\"));\n  });\n  $(\"grafik\").replaceChildren(svg);\n  const leg = $(\"legenda\");\n  leg.replaceChildren();\n  INFO.kelas.forEach((k) => {\n    const s = el(\"span\");\n    const t = el(\"span\", \"titik\"); t.style.background = k.warna;\n    s.appendChild(t); s.appendChild(document.createTextNode(k.nama));\n    leg.appendChild(s);\n  });\n  leg.appendChild(el(\"span\", \"\", \"Tiap batang = \" + r.langkah_detik + \" detik\"));\n}\n\nmulai().catch((e) => {\n  const kotak = $(\"masalah\");\n  kotak.appendChild(el(\"p\", \"\", \"Tidak bisa menghubungi server: \" + e.message));\n  kotak.hidden = false;\n});\n"}''')

# susunan lama -> _lama/
for lama in ("app.py", "layanan.py", "jalankan.sh", "web", "__pycache__"):
    p = os.path.join(TUJUAN, lama)
    if os.path.exists(p):
        if lama == "__pycache__":
            shutil.rmtree(p)
            continue
        os.makedirs(os.path.join(TUJUAN, "_lama"), exist_ok=True)
        t = os.path.join(TUJUAN, "_lama", lama)
        if os.path.exists(t):
            shutil.rmtree(t) if os.path.isdir(t) else os.remove(t)
        shutil.move(p, t)
        print("susunan lama dipindah:", lama, "-> _lama/")

for rel, isi in BERKAS.items():
    p = os.path.join(TUJUAN, rel)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    if os.path.exists(p) and open(p, encoding="utf-8").read() != isi:
        shutil.copy(p, p + ".lama")
    open(p, "w", encoding="utf-8").write(isi)
    print("ditulis:", p)
os.chmod(os.path.join(TUJUAN, "backend", "jalankan.sh"), 0o755)

